package api_test

import (
	"strings"
	"testing"

	"github.com/KogenAI/kogen-loop/api"
)

func TestDecodeTaskRequiresExactlyOneObject(t *testing.T) {
	for _, text := range []string{
		`null`,
		`{}]`,
		`{}}`,
		`{} garbage`,
	} {
		t.Run(text, func(t *testing.T) {
			if _, err := api.DecodeTask(strings.NewReader(text)); err == nil {
				t.Fatal("accepted a task that is not exactly one JSON object")
			}
		})
	}
	got, err := api.DecodeTask(strings.NewReader(" \n{\"prompt\":\"hello\"}\t\n"))
	if err != nil || got.Prompt != "hello" {
		t.Fatalf("valid object with surrounding whitespace: task %+v, error %v", got, err)
	}
}

func TestDecodeTaskRejectsUnknownTopLevelField(t *testing.T) {
	_, err := api.DecodeTask(strings.NewReader(`{"prompt":"hello","surprise":1}`))
	if err == nil {
		t.Fatal("accepted a task with an unknown top-level field")
	}
	if !strings.Contains(err.Error(), "surprise") {
		t.Fatalf("error does not identify the unknown field: %v", err)
	}
}

func TestDecodeTaskRejectsUnknownNestedField(t *testing.T) {
	for name, text := range map[string]string{
		"role":    `{"role":{"provider":"chatgpt","surprise":1}}`,
		"session": `{"session":{"dir":"d","surprise":1}}`,
	} {
		t.Run(name, func(t *testing.T) {
			_, err := api.DecodeTask(strings.NewReader(text))
			if err == nil {
				t.Fatal("accepted a task with an unknown nested field")
			}
			if !strings.Contains(err.Error(), "surprise") {
				t.Fatalf("error does not identify the unknown field: %v", err)
			}
		})
	}
}

func TestDecodeTaskAcceptsKnownNestedFields(t *testing.T) {
	text := `{"protocol":"kogen-loop/v1","prompt":"hello","role":{"provider":"openai-compatible","model":"m","effort":"high","base_url":"http://127.0.0.1:1"},"session":{"dir":"/s","resume":true}}`
	got, err := api.DecodeTask(strings.NewReader(text))
	if err != nil {
		t.Fatalf("rejected a valid task with known nested fields: %v", err)
	}
	if want := (api.Role{Provider: "openai-compatible", Model: "m", Effort: "high", BaseURL: "http://127.0.0.1:1"}); got.Role != want {
		t.Fatalf("role %+v, want %+v", got.Role, want)
	}
	if want := (api.SessionSpec{Dir: "/s", Resume: true}); got.Session != want {
		t.Fatalf("session %+v, want %+v", got.Session, want)
	}
}

